import AppKit
import CryptoKit

/// Polls the general pasteboard and records new content into the history.
final class ClipboardMonitor: NSObject {
    /// Pasteboard types that mark content as secret, temporary or machine-generated.
    /// Anything carrying one of these is never recorded.
    static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword"
    ]

    private static let maxRTFBytes = 512 * 1024

    private let store: HistoryStore
    private let settings: AppSettings
    private let pasteboard = NSPasteboard.general
    private var lastChangeCount: Int
    private var timer: Timer?

    init(store: HistoryStore, settings: AppSettings) {
        self.store = store
        self.settings = settings
        self.lastChangeCount = NSPasteboard.general.changeCount
        super.init()
    }

    func start() {
        guard timer == nil else { return }
        let newTimer = Timer(timeInterval: 0.5,
                             target: self,
                             selector: #selector(tick),
                             userInfo: nil,
                             repeats: true)
        newTimer.tolerance = 0.1
        RunLoop.main.add(newTimer, forMode: .common)
        timer = newTimer
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    @objc private func tick() {
        let changeCount = pasteboard.changeCount
        guard changeCount != lastChangeCount else { return }
        lastChangeCount = changeCount
        guard !settings.paused else { return }
        capture()
    }

    private func capture() {
        let types = pasteboard.types ?? []
        let rawTypes = Set(types.map { $0.rawValue })

        // Our own writes (pasting from the history) are not new content.
        if rawTypes.contains(PasteService.ownMarkerType.rawValue) { return }
        if !rawTypes.isDisjoint(with: ClipboardMonitor.skippedTypes) { return }

        let frontApp = NSWorkspace.shared.frontmostApplication
        let appName = frontApp?.localizedName
        let bundleID = frontApp?.bundleIdentifier
        if settings.isIgnored(appName: appName, bundleID: bundleID) { return }

        // Files first: Finder also puts the file name and icon on the pasteboard.
        if rawTypes.contains(NSPasteboard.PasteboardType.fileURL.rawValue),
           let urls = pasteboard.readObjects(forClasses: [NSURL.self],
                                             options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            let paths = urls.map { $0.path }
            let item = ClipboardItem(kind: .file,
                                     filePaths: paths,
                                     sourceAppName: appName,
                                     sourceBundleID: bundleID,
                                     contentHash: "file:" + paths.joined(separator: "\n"))
            store.insert(item)
            return
        }

        let string = pasteboard.string(forType: .string)
        let hasText = !(string ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let hasImage = rawTypes.contains(NSPasteboard.PasteboardType.png.rawValue)
            || rawTypes.contains(NSPasteboard.PasteboardType.tiff.rawValue)

        // Office apps add a picture of copied text, browsers add the URL of a
        // copied picture. Text wins unless it is just a single URL.
        let preferImage = hasImage && (!hasText || ContentClassifier.isLink(string ?? ""))
        if preferImage, captureImage(appName: appName, bundleID: bundleID) {
            return
        }

        if hasText, let text = string {
            let kind = ContentClassifier.classify(text)
            var rtf: Data?
            if rawTypes.contains(NSPasteboard.PasteboardType.rtf.rawValue),
               let data = pasteboard.data(forType: .rtf),
               data.count <= ClipboardMonitor.maxRTFBytes {
                rtf = data
            }
            let item = ClipboardItem(kind: kind,
                                     text: text,
                                     rtf: rtf,
                                     sourceAppName: appName,
                                     sourceBundleID: bundleID,
                                     contentHash: "text:" + ClipboardMonitor.sha256(Data(text.utf8)))
            store.insert(item)
            return
        }

        if hasImage && !preferImage {
            _ = captureImage(appName: appName, bundleID: bundleID)
        }
    }

    /// Stores the pasteboard image as PNG. Returns false if there was no usable image.
    private func captureImage(appName: String?, bundleID: String?) -> Bool {
        let limit = max(1, settings.maxImageMB) * 1_048_576

        var pngData: Data?
        var bitmap: NSBitmapImageRep?

        if let png = pasteboard.data(forType: .png), let rep = NSBitmapImageRep(data: png) {
            pngData = png
            bitmap = rep
        } else if let tiff = pasteboard.data(forType: .tiff), let rep = NSBitmapImageRep(data: tiff) {
            pngData = rep.representation(using: .png, properties: [:])
            bitmap = rep
        }

        guard let data = pngData, let rep = bitmap else { return false }
        // Too large for the user's limit: treat as handled so nothing else is recorded for it.
        guard data.count <= limit else { return true }

        let item = ClipboardItem(kind: .image,
                                 imageWidth: rep.pixelsWide,
                                 imageHeight: rep.pixelsHigh,
                                 sourceAppName: appName,
                                 sourceBundleID: bundleID,
                                 contentHash: "image:" + ClipboardMonitor.sha256(data))
        store.insert(item, imageData: data)
        return true
    }

    private static func sha256(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }
}
